  describe('available slots', () => {
    async function availableSlots(fromHours: number, toHours: number, duration: number) {
      return app.inject({
        method: 'GET',
        url: `/bookings/available-slots?roomId=${roomId}&from=${inHours(fromHours)}&to=${inHours(toHours)}&duration=${duration}`,
      });
    }

    it('returns the whole window as one slot when there are no bookings', async () => {
      const response = await availableSlots(24, 28, 60);
      expect(response.statusCode).toBe(200);
      expect(response.json().data).toHaveLength(1);
      expect(new Date(response.json().data[0].startsAt)).toEqual(new Date(inHours(24)));
      expect(new Date(response.json().data[0].endsAt)).toEqual(new Date(inHours(28)));
    });

    it('splits the window around an existing booking', async () => {
      await book(25, 26);
      const response = await availableSlots(24, 28, 60);
      expect(response.json().data).toHaveLength(2);
      expect(new Date(response.json().data[0].endsAt)).toEqual(new Date(inHours(25)));
      expect(new Date(response.json().data[1].startsAt)).toEqual(new Date(inHours(26)));
    });

    it('returns no slots when a booking covers the whole window', async () => {
      await book(24, 28);
      const response = await availableSlots(24, 28, 30);
      expect(response.json().data).toHaveLength(0);
    });

    it('excludes gaps shorter than the requested duration', async () => {
      await book(24.5, 25);
      await book(25.25, 26);
      const response = await availableSlots(24, 28, 60);
      const gapStarts = response.json().data.map((slot: { startsAt: string }) => slot.startsAt);
      expect(gapStarts).not.toContain(inHours(25));
    });

    it('answers 404 when the room does not exist', async () => {
      const response = await app.inject({
        method: 'GET',
        url: `/bookings/available-slots?roomId=missing&from=${inHours(24)}&to=${inHours(28)}&duration=30`,
      });
      expect(response.statusCode).toBe(404);
    });

    it('rejects a window where "from" is not before "to"', async () => {
      const response = await availableSlots(28, 24, 30);
      expect(response.statusCode).toBe(400);
      expect(response.json().error.code).toBe('VALIDATION_ERROR');
    });

    it('rejects a duration outside the bookable range', async () => {
      const tooShort = await availableSlots(24, 28, 10);
      expect(tooShort.statusCode).toBe(400);
      const tooLong = await availableSlots(24, 28, 600);
      expect(tooLong.statusCode).toBe(400);
    });
  });
});

